static void test_insert_foreach_sorted_order(void) {
    rbtree_t *t = rb_create(NULL);
    assert(t != NULL);
    const char *keys[] = {"mango", "kiwi", "pear", "fig", "lime", "apricot"};
    size_t n = sizeof(keys) / sizeof(keys[0]);
