    for (int i = 0; i < 26; i++) {
        assert(rb_find(t, keys[i]) == &values[i]);
    }
    rb_destroy(t);
}

int main(void) {
    test_size_empty_tree();
    test_destroy_null_is_safe();
    test_destroy_empty_tree();
    test_find_empty_tree();
    test_find_present_key();
